package com.limelight.rhremote;

import android.app.Activity;
import android.os.Looper;
import android.view.*;
import android.view.inputmethod.*;
import android.widget.*;
import com.limelight.R;
import com.limelight.nvstream.http.ComputerDetails;
import java.util.*;
import org.json.JSONObject;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import static org.junit.Assert.*;

/** Global navigation and the same cached native device rows used by Home. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=28,qualifiers="w1200dp-h800dp-mdpi",shadows=RhAdmissionTest.Controls.class)
public final class RhWorkspaceFocusTest {
    private Activity activity;private RhHome home;private RhDeviceBrowser browser;private View root;
    private final List<String> calls=new ArrayList<>();
    private ComputerDetails a,b,c;
    @After public void cleanup(){if(home!=null)home.dispose();if(activity!=null)activity.finish();}
    private ComputerDetails device(String id){ComputerDetails value=new ComputerDetails();value.uuid=id;value.name="Focus "+id;value.manualAddress=new ComputerDetails.AddressTuple("192.0.2.120",47989);value.state=ComputerDetails.State.ONLINE;return value;}
    private void scene(boolean dark){activity=Robolectric.buildActivity(Activity.class).setup().get();activity.setTheme(R.style.RhTheme);RhShared.theme(activity,dark);browser=new RhDeviceBrowser(activity,(id,args)->calls.add(id+":"+args.optString("uuid",args.optString("query"))));activity.setContentView(browser);root=browser;a=device("a");b=device("b");c=device("c");browser.update(Arrays.asList(a,b,c),"a","");layout(1200,800);}
    private void layout(int width,int height){org.robolectric.shadows.ShadowDisplayManager.changeDisplay(0,"w"+width+"dp-h"+height+"dp-mdpi");activity.getWindow().setLayout(width,height);for(int i=0;i<3;i++){root.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));root.layout(0,0,width,height);Shadows.shadowOf(Looper.getMainLooper()).idle();}assertEquals("Actual test viewport",width,root.getWidth());}
    private View find(View view,String description){if(!RhViewOrigin.visibleWithin(root,view))return null;if(description.equals(view.getContentDescription())||description.equals(view.getTag()))return view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){View result=find(((ViewGroup)view).getChildAt(i),description);if(result!=null)return result;}return null;}
    private View row(String id){View value=find(root,"选择设备 Focus "+id);assertNotNull(id,value);return value;}
    private void focus(View value){assertTrue("Cannot focus "+value.getContentDescription(),value.requestFocusFromTouch());assertTrue(value.hasFocus());}
    private void focusStyle(View value){assertFalse("Use the themed focus indication",value.getDefaultFocusHighlightEnabled());android.graphics.drawable.Drawable background=value.getBackground();assertTrue("Missing focus states: "+value.getContentDescription(),background.isStateful());background.setState(new int[]{android.R.attr.state_enabled});android.graphics.drawable.Drawable normal=background.getCurrent();background.setState(new int[]{android.R.attr.state_enabled,android.R.attr.state_focused});assertNotSame(normal,background.getCurrent());background.setState(value.getDrawableState());}
    @Test public void applicationNavigationShowsFocusInEitherShellAndTheme()throws Exception{
        for(boolean dark:new boolean[]{false,true}){activity=Robolectric.buildActivity(Activity.class).setup().get();activity.setTheme(R.style.RhTheme);RhShared.theme(activity,dark);home=new RhHome(activity,new RhHome.Actions(){public void connect(ComputerDetails d){throw new AssertionError();}public void add(String s){throw new AssertionError();}public void advanced(){}public void pair(ComputerDetails d,String p){throw new AssertionError();}public void cancelPair(){}public void refresh(){}});home.resumed();root=((ViewGroup)activity.findViewById(android.R.id.content)).getChildAt(0);
            for(int width:new int[]{1200,360}){layout(width,800);for(String id:new String[]{"app.settings.open","添加电脑"}){View control=find(root,id.equals("添加电脑")?id:"nav:"+id);assertNotNull(id,control);focusStyle(control);focus(control);}}home.dispose();home=null;activity.finish();}
    }
    @Test public void deviceRowsExposeFocusAndSelectionWithoutSystemHighlight(){scene(false);assertTrue("Current device is not marked selected",row("a").isSelected());assertFalse(row("b").isSelected());focus(row("b"));focusStyle(row("b"));}
    @Test public void addingAndRemovingOtherDevicesPreservesTheFocusedRow(){scene(false);View current=row("b");focus(current);ComputerDetails d=device("d");browser.update(Arrays.asList(a,b,c,d),"a","");layout(1200,800);assertSame(current,row("b"));assertTrue("Adding another device detached the focused row",current.hasFocus());browser.update(Arrays.asList(b,c,d),"b","");layout(1200,800);assertSame(current,row("b"));assertTrue("Removing another device lost row focus",current.hasFocus());assertTrue(calls.isEmpty());}
    @Test public void reorderingKeepsFocusWithoutSelectingOrConnecting(){scene(false);View current=row("b");focus(current);browser.update(Arrays.asList(c,b,a),"a","");layout(1200,800);assertTrue("Reordering detached the focused row",current.hasFocus());browser.update(Arrays.asList(b,c,a),"a","");layout(1200,800);assertTrue("Moving the focused row lost its focus",current.hasFocus());assertFalse(current.isSelected());assertTrue(row("a").isSelected());assertTrue(calls.isEmpty());}
    @Test public void filteringCannotRestoreAnInvisibleOldRow(){scene(false);View old=row("b");focus(old);EditText search=(EditText)find(root,"搜索名称或地址");focus(search);browser.update(Arrays.asList(a,b,c),"b","Focus a");layout(1200,800);assertFalse(RhViewOrigin.visibleWithin(root,old));old.performClick();assertTrue(calls.isEmpty());assertTrue(search.hasFocus());browser.update(Arrays.asList(a,b,c),"b","no matching fixture");layout(1200,800);assertTrue(search.hasFocus());assertTrue(calls.isEmpty());}
    @Test public void enterSelectsOnceAndRefreshKeepsTheFocusStyle(){scene(false);View current=row("b");focus(current);for(int phase:new int[]{KeyEvent.ACTION_DOWN,KeyEvent.ACTION_UP})current.dispatchKeyEvent(new KeyEvent(1000,1000,phase,KeyEvent.KEYCODE_ENTER,0));assertEquals(Collections.singletonList("device.select:b"),calls);b.state=ComputerDetails.State.OFFLINE;browser.update(Arrays.asList(a,b,c),"b","");layout(1200,800);assertTrue(current.hasFocus());assertTrue(current.isSelected());focusStyle(current);}
    @Test public void hiddenSearchConnectionsCannotChangeTheVisibleWorkspaceQuery(){scene(false);EditText search=(EditText)find(root,"搜索名称或地址");focus(search);InputConnection connection=search.onCreateInputConnection(new EditorInfo());assertNotNull(connection);browser.setVisibility(View.GONE);connection.commitText("retired query",1);Shadows.shadowOf(Looper.getMainLooper()).idle();assertTrue("Hidden search emitted a new query",calls.isEmpty());browser.setVisibility(View.VISIBLE);browser.update(Arrays.asList(a,b,c),"a","");layout(1200,800);focus(search);search.setText("current query");assertEquals(Collections.singletonList("devices.filter:current query"),calls);}
    @Test public void homeStatusRefreshDoesNotCollapseTheFocusedListDuringParentMeasurement()throws Exception{
        RhAppearanceFlowTest fixture=new RhAppearanceFlowTest();fixture.create(false);activity=fixture.activity;home=fixture.home;home.resumed();root=((ViewGroup)activity.findViewById(android.R.id.content)).getChildAt(0);b=device("b");home.update(b);home.perform("device.select",RhActions.obj("uuid","host"));layout(1200,800);View current=row("b");focus(current);ComputerDetails host=device("host");host.name="winserver";host.state=ComputerDetails.State.OFFLINE;home.update(host);layout(1200,800);assertTrue("A parent measurement collapsed the still-wide list",current.hasFocus());assertEquals("host",home.state().getString("selected"));
    }
    private ScrollView populatedList(){scene(false);List<ComputerDetails> many=new ArrayList<>();for(int i=0;i<9;i++)many.add(device("row"+i));browser.update(many,"row0","");layout(360,500);return (ScrollView)row("row6").getParent().getParent();}
    private void fullyVisible(View target){android.graphics.Rect visible=new android.graphics.Rect();assertTrue("Row is outside the list viewport",target.getGlobalVisibleRect(visible));assertEquals("Focused row is clipped horizontally",target.getWidth(),visible.width());assertEquals("Focused row is clipped vertically",target.getHeight(),visible.height());}
    @Test public void movingTheFocusedRowAboveTheViewportRevealsItAfterLayout(){ScrollView list=populatedList();View current=row("row6");focus(current);list.scrollTo(0,current.getTop());assertTrue("Fixture must actually scroll",list.getScrollY()>0);List<ComputerDetails> reordered=new ArrayList<>();reordered.add(device("row6"));for(int i=0;i<9;i++)if(i!=6)reordered.add(device("row"+i));browser.update(reordered,"row0","");layout(360,500);assertTrue(current.hasFocus());fullyVisible(current);assertTrue(calls.isEmpty());}
    @Test public void statusRefreshDoesNotPullBackAManuallyScrolledList(){ScrollView list=populatedList();View current=row("row0");focus(current);list.scrollTo(0,row("row8").getBottom());int before=list.getScrollY();assertTrue(before>0);List<ComputerDetails> same=new ArrayList<>();for(int i=0;i<9;i++)same.add(device("row"+i));same.get(2).state=ComputerDetails.State.OFFLINE;browser.update(same,"row0","");layout(360,500);assertEquals("A status-only refresh moved the user's viewport",before,list.getScrollY());assertTrue(calls.isEmpty());}
    @Test public void delayedReorderRevealCannotMoveTheCurrentSearchViewport(){ScrollView list=populatedList();View current=row("row6");focus(current);list.scrollTo(0,current.getTop());List<ComputerDetails> reordered=new ArrayList<>();reordered.add(device("row6"));for(int i=0;i<9;i++)if(i!=6)reordered.add(device("row"+i));browser.update(reordered,"row0","");focus(find(root,"搜索名称或地址"));int before=list.getScrollY();layout(360,500);assertEquals("Old row reveal scrolled after focus moved to search",before,list.getScrollY());assertTrue(find(root,"搜索名称或地址").hasFocus());}
}
